/// Re-exported so that macros can name PyO3 items through `$crate`.
pub use pyo3;

/// Reads a builtin such as `len`, raising `NameError` if it does not exist.
///
/// Like `LOAD_GLOBAL`, it looks in the namespace of the `builtins` module,
/// not at its attributes: `__annotations__` or `__dict__` are attributes of
/// every module object but not builtins.
pub fn builtin<'py>(py: Python<'py>, name: &'static str) -> PyResult<Bound<'py, PyAny>> {
    match builtins_module(py)?.dict().get_item(interned(py, name))? {
        Some(value) => Ok(value),
        None => Err(raised(PyNameError::new_err(format!(
            "name '{name}' is not defined"
        )))),
    }
}

pub(crate) fn builtins_module(py: Python<'_>) -> PyResult<&Bound<'_, PyModule>> {
    static BUILTINS: PyOnceLock<Py<PyModule>> = PyOnceLock::new();
    BUILTINS
        .get_or_try_init(py, || py.import("builtins").map(Bound::unbind))
        .map(|module| module.bind(py))
}

/// An exception created in Rust, made a real exception object right away.
///
/// `PyErr::new_err` creates the exception object lazily, when it is first
/// needed. Implicit chaining (`__context__`) happens then, so an error created
/// inside an `except` block but materialized after it would miss the
/// exception being handled. Errors the runtime raises go through here.
pub(crate) fn raised(err: PyErr) -> PyErr {
    Python::attach(|py| {
        err.value(py);
    });
    err
}

/// Makes `tp_name` of the class `T` the plain `name` that CPython's own
/// class of that name has (`generator`), which error messages such as
/// `cannot pickle 'generator' object` use. PyO3 always puts a module in
/// front (`builtins.generator`); `__name__` and `__module__` are not
/// affected. Called when an object of the class is created.
pub(crate) fn plain_type_name<T: PyTypeInfo>(py: Python<'_>, name: &'static std::ffi::CStr) {
    let ty = T::type_object_raw(py);
    // SAFETY: attached; `ty` is the class's type object, which lives as long
    // as the interpreter. A heap type owns the buffer of its original name
    // separately (`_ht_tpname`), so pointing `tp_name` at a static string
    // leaks and frees nothing; CPython's `__name__` setter does the same.
    unsafe {
        if !std::ptr::eq((*ty).tp_name, name.as_ptr()) {
            (*ty).tp_name = name.as_ptr();
            ffi::PyType_Modified(ty);
        }
    }
}

/// The name CPython uses for the type of `value` in error messages
/// (`tp_name`, e.g. `int` or `datetime.date`).
pub(crate) fn type_name(value: &Bound<'_, PyAny>) -> String {
    // SAFETY: the type of a valid object has a NUL-terminated `tp_name`.
    unsafe { std::ffi::CStr::from_ptr((*value.get_type_ptr()).tp_name) }
        .to_string_lossy()
        .into_owned()
}

/// Reads a local variable that might not be assigned yet, raising
/// `UnboundLocalError` like Python does.
pub fn local<'a, 'py>(
    value: &'a Option<Bound<'py, PyAny>>,
    name: &str,
) -> PyResult<&'a Bound<'py, PyAny>> {
    value.as_ref().ok_or_else(|| unbound_local(name))
}

/// Deletes a local variable like `del name` does, raising `UnboundLocalError`
/// if it is not assigned.
pub fn del_local(value: &mut Option<Bound<'_, PyAny>>, name: &str) -> PyResult<()> {
    match value.take() {
        Some(_) => Ok(()),
        None => Err(unbound_local(name)),
    }
}

fn unbound_local(name: &str) -> PyErr {
    let err = PyUnboundLocalError::new_err(format!(
        "cannot access local variable '{name}' where it is not associated with a value"
    ));
    raised(err)
}

/// Guards against unbounded recursion in functions that call each other
/// directly, turning a would-be stack overflow into `RecursionError`.
///
/// Calls that go through Python (`PyObject_Call`) already get this check, so
/// only functions in a cycle of direct Rust calls need it.
pub struct RecursionGuard<'py> {
    _py: Python<'py>,
}

impl<'py> RecursionGuard<'py> {
    pub fn enter(py: Python<'py>) -> PyResult<Self> {
        // `PyErr::fetch` compares every fetched exception with PyO3's
        // `PanicException`, creating that type on first use. Creating it with
        // the stack already exhausted fails and deadlocks PyO3's lazy type
        // initialisation, so make sure it exists while there is still room.
        pyo3::panic::PanicException::type_object_raw(py);
        // SAFETY: we are attached to the interpreter; a successful enter is
        // always balanced by the leave in `Drop`.
        let failed =
            unsafe { pyo3::ffi::Py_EnterRecursiveCall(c" while calling a Python object".as_ptr()) };
        if failed != 0 {
            return Err(PyErr::fetch(py));
        }
        Ok(Self { _py: py })
    }
}

impl Drop for RecursionGuard<'_> {
    fn drop(&mut self) {
        // SAFETY: paired with the successful `Py_EnterRecursiveCall` above.
        unsafe { pyo3::ffi::Py_LeaveRecursiveCall() }
    }
}
